mapper.select:
/* master.mpst.selectAgingGrDtList */ SELECT A.YYYYMM, A.KEP_DEPT, (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = 'KRKORE0001' AND TYPE = 'C001' AND CODE = A.KEP_DEPT) AS KEP_DEPT_NAME, F_SPLIT(A.CATEG_NAME, ' > ', 2) AS CATEG_NAME, A.ITEM_NO, A.DESCRIPTION, A.SPECIFICATION, A.UNIT_MEASURE, A.MAKER_NAME, A.STOCK_PRICE, A.STOCK_QTY, A.D01_QTY, A.D02_QTY, A.D03_QTY, A.D04_QTY, A.D05_QTY, A.D06_QTY, A.D07_QTY, A.D08_QTY, A.D09_QTY, A.D10_QTY, A.D11_QTY, A.D12_QTY, A.D13_QTY + A.ETC_QTY AS ETC_QTY FROM KEP_STOCK_AGING_IPGO A WHERE 1=1 AND A.YYYYMM = #{st_yyyymm}
AND A.KEP_DEPT = #{st_dept_code}
AND A.ITEM_NO LIKE '%' || #{st_item_no} || '%'
ORDER BY KEP_DEPT_NAME, CATEG_NAME, ITEM_NO
